      .product-link:hover,
      .editorial-card a:hover {
        color: var(--color-link);
        text-decoration: underline;
        text-decoration-thickness: 0.14em;
        text-underline-offset: 0.18em;
      }

      .product-meta,
      .deal-card p,
      .editorial-card p {
        margin: 0;
        color: var(--color-muted-text);
      }

      .price-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
        margin-top: auto;
      }

      .price {
        color: var(--color-text);
        font-size: 1.35rem;
        font-weight: 950;
      }

      .product-action:hover,
      .icon-button:hover,
      .text-link:hover {
        border-color: var(--color-link);
        color: var(--color-link);
      }

      .deals {
        background:
          linear-gradient(180deg, transparent, #111827 20%, #111827 80%, transparent);
      }

      .deal-card {
        position: relative;
        overflow: hidden;
        min-height: 18rem;
        padding: 1.4rem;
      }

      .deal-card::after {
        content: "";
        position: absolute;
        right: -3rem;
        bottom: -3rem;
        width: 11rem;
        height: 11rem;
        border-radius: 999px;
        background: var(--deal-color);
