      .deal-label {
        display: inline-flex;
        margin-bottom: 1.25rem;
        border-radius: 999px;
        background: var(--color-link);
        color: #111827;
        font-weight: 950;
        padding: 0.35rem 0.7rem;
      }

      .deal-card h3 {
