      .newsletter {
        display: grid;
        grid-template-columns: 1fr auto;
        gap: 1rem;
        align-items: center;
        border: 1px solid var(--color-border);
        border-radius: 2rem;
        background:
          radial-gradient(circle at 12% 20%, #22d3ee55, transparent 18rem),
          radial-gradient(circle at 90% 80%, #d946ef55, transparent 18rem),
          var(--color-surface);
        padding: clamp(1.5rem, 4vw, 2.5rem);
      }

      .newsletter h2 {
        margin: 0;
        font-size: clamp(1.8rem, 4vw, 3rem);
        letter-spacing: -0.05em;
        line-height: 1;
      }

      .newsletter p {
        max-width: 46rem;
        margin: 0.75rem 0 0;
        color: var(--color-muted-text);
      }

      .site-footer {
        border-top: 1px solid var(--color-border);
        background: #080b12;
        margin-top: 3rem;
        padding-block: 2rem;
      }

      .footer-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
      }

      .footer-inner p {
        margin: 0;
        color: var(--color-muted-text);
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        clip-path: inset(50%);
        white-space: nowrap;
      }

      @media (prefers-reduced-motion: no-preference) {
        html {
          scroll-behavior: smooth;
        }

        .product-card,
        .deal-card,
        .editorial-card,
        .hero-card {
          transition:
            border-color 180ms ease,
            transform 180ms ease;
        }

        .product-card:hover,
        .deal-card:hover,
        .editorial-card:hover,
        .hero-card:hover {
          border-color: var(--color-link);
          transform: translateY(-4px);
        }
      }

      @media (max-width: 900px) {
        .nav-shell,
        .footer-inner,
        .section-heading,
        .newsletter {
          align-items: flex-start;
          flex-direction: column;
        }

        .nav-shell,
        .footer-inner {
          padding-block: 1rem;
        }

        .primary-nav ul,
        .footer-nav ul {
          flex-wrap: wrap;
        }

        .hero,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .product-grid,
        .deal-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .editorial-card:first-child {
          grid-column: 1 / -1;
        }
      }

      @media (max-width: 560px) {
        .nav-shell,
        .header-actions {
          align-items: stretch;
        }

        .header-actions {
          width: 100%;
        }

        .header-actions .pill-button {
          flex: 1;
          justify-content: center;
        }

        .hero h1 {
          font-size: clamp(2.8rem, 18vw, 4.5rem);
        }

        .product-grid,
        .deal-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .hero-card-visual {
          min-height: 16rem;
        }

        .hero-actions,
        .price-row {
          align-items: stretch;
          flex-direction: column;
        }

        .pill-button,
        .text-link,
        .product-action {
          justify-content: center;
          text-align: center;
        }
      }

      @media (forced-colors: active) {
        body {
          background: Canvas;
          color: CanvasText;
        }

        body::before,
        .hero-card-visual,
        .product-media,
        .editorial-art,
        .deal-card::after {
          display: none;
        }

        .site-header,
        .site-footer,
        .product-card,
        .deal-card,
        .editorial-card,
        .hero-card,
        .newsletter,
        .pill-button,
        .icon-button,
        .product-action,
        .text-link,
        .brand-mark {
          border: 2px solid ButtonBorder;
          background: Canvas;
          color: CanvasText;
          box-shadow: none;
        }

        .pill-button,
        .deal-label,
        .skip-link {
          background: ButtonFace;
          color: ButtonText;
        }

        :focus-visible {
          outline: 3px solid Highlight;
          box-shadow: none;
        }
      }
    </style>
