        color: var(--color-link);
        font-size: 1.6rem;
        line-height: 1;
      }

      .metric span {
        color: var(--color-muted-text);
      }

      .section {
        padding-block: 3.5rem;
      }

      .section-heading {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.4rem;
      }

      .section-heading h2 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.3rem);
        line-height: 1;
        letter-spacing: -0.05em;
