      .deal-card h3,
      .editorial-card h3 {
        margin: 0;
        line-height: 1.15;
      }

      .product-link,
      .editorial-card a {
        color: var(--color-text);
        font-size: 1.15rem;
        font-weight: 900;
        text-decoration: none;
