      body {
        margin: 0;
        background:
          radial-gradient(circle at top left, #172554 0, transparent 34rem),
          radial-gradient(circle at 85% 10%, #581c87 0, transparent 28rem),
          var(--color-bg);
        color: var(--color-text);
        line-height: 1.6;
      }

      body::before {
        content: "";
        position: fixed;
        inset: 0;
        pointer-events: none;
        background-image:
          linear-gradient(#ffffff08 1px, transparent 1px),
          linear-gradient(90deg, #ffffff08 1px, transparent 1px);
        background-size: 64px 64px;
        mask-image: linear-gradient(to bottom, #000000 0%, transparent 70%);
      }

      a {
        color: inherit;
      }

      img {
        display: block;
        max-width: 100%;
      }

      button,
      a {
        -webkit-tap-highlight-color: transparent;
      }

      :focus-visible {
