      .skip-link {
        position: absolute;
        left: 1rem;
        top: 1rem;
        z-index: 20;
        transform: translateY(-150%);
        border-radius: 999px;
        background: var(--color-link);
        color: #111827;
        font-weight: 800;
        padding: 0.75rem 1rem;
        text-decoration: none;
      }

      .skip-link:focus {
        transform: translateY(0);
