        top: 0;
        z-index: 10;
        border-bottom: 1px solid var(--color-border);
        background: #080b12;
      }

      .nav-shell,
      .section,
      .footer-inner {
        width: min(1180px, calc(100% - 2rem));
        margin-inline: auto;
      }

      .nav-shell {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        min-height: 76px;
      }

      .brand {
        display: inline-flex;
        align-items: center;
        gap: 0.75rem;
        color: var(--color-text);
        font-size: 1.05rem;
        font-weight: 900;
        letter-spacing: 0.04em;
        text-decoration: none;
        text-transform: uppercase;
