      .brand-mark {
        display: grid;
        width: 2.75rem;
        height: 2.75rem;
        place-items: center;
        border: 1px solid var(--color-brand);
        border-radius: 1rem;
        background: linear-gradient(135deg, var(--color-brand), var(--color-accent));
        color: #08111f;
        font-weight: 950;
