      .primary-nav ul,
      .footer-nav ul {
        display: flex;
        align-items: center;
        gap: 0.25rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .primary-nav a,
      .footer-nav a {
        display: inline-flex;
        min-height: 44px;
        align-items: center;
        border-radius: 999px;
        color: var(--color-muted-text);
        font-weight: 750;
        padding: 0.5rem 0.85rem;
        text-decoration: none;
      }

      .primary-nav a:hover,
      .footer-nav a:hover {
        background: var(--color-surface-raised);
        color: var(--color-text);
      }

      .header-actions {
        display: flex;
        align-items: center;
        gap: 0.75rem;
      }

      .pill-button,
      .icon-button,
      .product-action,
      .text-link {
        border: 1px solid var(--color-border);
        border-radius: 999px;
        background: var(--color-surface-raised);
        color: var(--color-text);
        cursor: pointer;
        font: inherit;
        font-weight: 800;
        min-height: 44px;
        padding: 0.68rem 1rem;
        text-decoration: none;
      }

      .pill-button {
        background: linear-gradient(135deg, var(--color-link), #fb923c);
        border-color: transparent;
        color: #111827;
      }

      .icon-button {
        display: inline-grid;
        min-width: 44px;
        place-items: center;
        padding-inline: 0.8rem;
      }

      .cart-count {
        display: inline-grid;
        min-width: 1.35rem;
        min-height: 1.35rem;
        margin-left: 0.35rem;
        place-items: center;
        border-radius: 999px;
        background: var(--color-link);
        color: #111827;
        font-size: 0.78rem;
      }

      main {
        outline: none;
      }

      .hero {
        display: grid;
        grid-template-columns: minmax(0, 1.08fr) minmax(18rem, 0.92fr);
        gap: clamp(1.5rem, 4vw, 4rem);
        align-items: center;
        padding-block: clamp(3rem, 8vw, 7rem) 3rem;
      }

      .eyebrow {
        display: inline-flex;
        width: fit-content;
        align-items: center;
        gap: 0.5rem;
        border: 1px solid var(--color-border);
        border-radius: 999px;
        background: var(--color-surface);
        color: var(--color-link);
        font-size: 0.82rem;
        font-weight: 850;
        letter-spacing: 0.08em;
        padding: 0.35rem 0.7rem;
        text-transform: uppercase;
      }

      .hero h1 {
        max-width: 12ch;
        margin: 1rem 0;
        font-size: clamp(3.2rem, 9vw, 6.8rem);
        line-height: 0.92;
        letter-spacing: -0.08em;
      }

      .hero-copy {
        max-width: 64ch;
        color: var(--color-muted-text);
        font-size: clamp(1.05rem, 2vw, 1.3rem);
      }

      .hero-actions {
        display: flex;
        flex-wrap: wrap;
        gap: 0.9rem;
        margin-top: 1.8rem;
      }

      .text-link {
        display: inline-flex;
        align-items: center;
        gap: 0.4rem;
        background: transparent;
      }

      .hero-card {
        overflow: hidden;
        border: 1px solid var(--color-border);
        border-radius: 2rem;
        background:
          linear-gradient(145deg, #ffffff14, transparent 45%),
          var(--color-surface);
        box-shadow: var(--shadow-card);
      }

      .hero-card-visual {
        min-height: 22rem;
        background:
          radial-gradient(circle at 50% 28%, #facc15 0 5rem, transparent 5.1rem),
          radial-gradient(circle at 66% 50%, #22d3ee 0 6.6rem, transparent 6.7rem),
          radial-gradient(circle at 38% 62%, #d946ef 0 7.8rem, transparent 7.9rem),
          linear-gradient(135deg, #111827, #312e81);
      }

      .hero-card-body {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
        padding: 1.2rem;
      }

      .metric {
        margin: 0;
      }

      .metric strong {
        display: block;
        color: var(--color-link);
        font-size: 1.6rem;
        line-height: 1;
      }

      .metric span {
        color: var(--color-muted-text);
      }

      .section {
        padding-block: 3.5rem;
      }

      .section-heading {
        display: flex;
        align-items: end;
        justify-content: space-between;
        gap: 1rem;
        margin-bottom: 1.4rem;
      }

      .section-heading h2 {
        margin: 0;
        font-size: clamp(2rem, 5vw, 3.3rem);
        line-height: 1;
        letter-spacing: -0.05em;
      }

      .section-heading p {
        max-width: 40rem;
        margin: 0.55rem 0 0;
        color: var(--color-muted-text);
      }

      .product-grid,
      .deal-grid,
      .editorial-grid {
        display: grid;
        gap: 1rem;
        margin: 0;
        padding: 0;
        list-style: none;
      }

      .product-grid {
        grid-template-columns: repeat(4, minmax(0, 1fr));
      }

      .deal-grid {
        grid-template-columns: repeat(3, minmax(0, 1fr));
      }

      .editorial-grid {
        grid-template-columns: 1.2fr 0.8fr 0.8fr;
      }

      .product-card,
      .deal-card,
      .editorial-card {
        height: 100%;
        border: 1px solid var(--color-border);
        border-radius: 1.5rem;
        background: var(--color-surface);
        box-shadow: 0 16px 50px #000000;
      }

      .product-card {
        display: flex;
        flex-direction: column;
        overflow: hidden;
      }

      .product-media {
        display: grid;
        min-height: 14rem;
        place-items: center;
        background: linear-gradient(135deg, var(--swatch), #111827 72%);
      }

      .product-shape {
        width: 58%;
        aspect-ratio: 1;
        border-radius: var(--shape);
        background:
          radial-gradient(circle at 30% 25%, #ffffff, transparent 18%),
          linear-gradient(145deg, #ffffff, var(--swatch));
        box-shadow: 0 20px 55px #000000;
      }

      .product-body {
        display: flex;
        flex: 1;
        flex-direction: column;
        gap: 0.85rem;
        padding: 1rem;
      }

      .product-card h3,
      .deal-card h3,
      .editorial-card h3 {
        margin: 0;
        line-height: 1.15;
      }

      .product-link,
      .editorial-card a {
        color: var(--color-text);
        font-size: 1.15rem;
        font-weight: 900;
        text-decoration: none;
      }

      .product-link:hover,
      .editorial-card a:hover {
        color: var(--color-link);
        text-decoration: underline;
        text-decoration-thickness: 0.14em;
        text-underline-offset: 0.18em;
      }

      .product-meta,
      .deal-card p,
      .editorial-card p {
        margin: 0;
        color: var(--color-muted-text);
      }

      .price-row {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 0.75rem;
        margin-top: auto;
      }

      .price {
        color: var(--color-text);
        font-size: 1.35rem;
        font-weight: 950;
      }

      .product-action:hover,
      .icon-button:hover,
      .text-link:hover {
        border-color: var(--color-link);
        color: var(--color-link);
      }

      .deals {
        background:
          linear-gradient(180deg, transparent, #111827 20%, #111827 80%, transparent);
      }

      .deal-card {
        position: relative;
        overflow: hidden;
        min-height: 18rem;
        padding: 1.4rem;
      }

      .deal-card::after {
        content: "";
        position: absolute;
        right: -3rem;
        bottom: -3rem;
        width: 11rem;
        height: 11rem;
        border-radius: 999px;
        background: var(--deal-color);
      }

      .deal-label {
        display: inline-flex;
        margin-bottom: 1.25rem;
        border-radius: 999px;
        background: var(--color-link);
        color: #111827;
        font-weight: 950;
        padding: 0.35rem 0.7rem;
      }

      .deal-card h3 {
        max-width: 12ch;
        font-size: clamp(1.8rem, 4vw, 3.2rem);
        letter-spacing: -0.06em;
      }

      .deal-card p {
        max-width: 24rem;
        margin-top: 0.85rem;
      }

      .editorial-card {
        display: flex;
        min-height: 18rem;
        flex-direction: column;
        justify-content: end;
        overflow: hidden;
      }

      .editorial-card:first-child {
        min-height: 26rem;
      }

      .editorial-art {
        flex: 1;
        min-height: 10rem;
        background:
          linear-gradient(135deg, var(--article-color), transparent),
          repeating-linear-gradient(45deg, #ffffff12 0 1px, transparent 1px 16px),
          #111827;
      }

      .editorial-body {
        padding: 1.2rem;
      }

      .tag {
        display: block;
        color: var(--color-link);
        font-size: 0.78rem;
        font-weight: 900;
        letter-spacing: 0.08em;
        margin-bottom: 0.5rem;
        text-transform: uppercase;
      }

      .newsletter {
        display: grid;
        grid-template-columns: 1fr auto;
        gap: 1rem;
        align-items: center;
        border: 1px solid var(--color-border);
        border-radius: 2rem;
        background:
          radial-gradient(circle at 12% 20%, #22d3ee55, transparent 18rem),
          radial-gradient(circle at 90% 80%, #d946ef55, transparent 18rem),
          var(--color-surface);
        padding: clamp(1.5rem, 4vw, 2.5rem);
      }

      .newsletter h2 {
        margin: 0;
        font-size: clamp(1.8rem, 4vw, 3rem);
        letter-spacing: -0.05em;
        line-height: 1;
      }

      .newsletter p {
        max-width: 46rem;
        margin: 0.75rem 0 0;
        color: var(--color-muted-text);
      }

      .site-footer {
        border-top: 1px solid var(--color-border);
        background: #080b12;
        margin-top: 3rem;
        padding-block: 2rem;
      }

      .footer-inner {
        display: flex;
        align-items: center;
        justify-content: space-between;
        gap: 1rem;
      }

      .footer-inner p {
        margin: 0;
        color: var(--color-muted-text);
      }

      .sr-only {
        position: absolute;
        width: 1px;
        height: 1px;
        overflow: hidden;
        clip: rect(0 0 0 0);
        clip-path: inset(50%);
        white-space: nowrap;
      }

      @media (prefers-reduced-motion: no-preference) {
        html {
          scroll-behavior: smooth;
        }

        .product-card,
        .deal-card,
        .editorial-card,
        .hero-card {
          transition:
            border-color 180ms ease,
            transform 180ms ease;
        }

        .product-card:hover,
        .deal-card:hover,
        .editorial-card:hover,
        .hero-card:hover {
          border-color: var(--color-link);
          transform: translateY(-4px);
        }
      }

      @media (max-width: 900px) {
        .nav-shell,
        .footer-inner,
        .section-heading,
        .newsletter {
          align-items: flex-start;
          flex-direction: column;
        }

        .nav-shell,
        .footer-inner {
          padding-block: 1rem;
        }

        .primary-nav ul,
        .footer-nav ul {
          flex-wrap: wrap;
        }

        .hero,
        .newsletter {
          grid-template-columns: 1fr;
        }

        .product-grid,
        .deal-grid,
        .editorial-grid {
          grid-template-columns: repeat(2, minmax(0, 1fr));
        }

        .editorial-card:first-child {
          grid-column: 1 / -1;
        }
      }

      @media (max-width: 560px) {
        .nav-shell,
        .header-actions {
          align-items: stretch;
        }

        .header-actions {
          width: 100%;
        }

        .header-actions .pill-button {
          flex: 1;
          justify-content: center;
        }

        .hero h1 {
          font-size: clamp(2.8rem, 18vw, 4.5rem);
        }

        .product-grid,
        .deal-grid,
        .editorial-grid {
          grid-template-columns: 1fr;
        }

        .hero-card-visual {
          min-height: 16rem;
        }

        .hero-actions,
        .price-row {
          align-items: stretch;
          flex-direction: column;
        }

        .pill-button,
        .text-link,
        .product-action {
          justify-content: center;
          text-align: center;
        }
      }

      @media (forced-colors: active) {
        body {
          background: Canvas;
          color: CanvasText;
        }

        body::before,
        .hero-card-visual,
        .product-media,
        .editorial-art,
        .deal-card::after {
          display: none;
        }

        .site-header,
        .site-footer,
        .product-card,
        .deal-card,
        .editorial-card,
        .hero-card,
        .newsletter,
        .pill-button,
        .icon-button,
        .product-action,
        .text-link,
        .brand-mark {
          border: 2px solid ButtonBorder;
          background: Canvas;
          color: CanvasText;
          box-shadow: none;
        }

        .pill-button,
        .deal-label,
        .skip-link {
          background: ButtonFace;
          color: ButtonText;
        }

        :focus-visible {
          outline: 3px solid Highlight;
          box-shadow: none;
        }

        .brand,
        .primary-nav a,
        .footer-nav a,
        .eyebrow,
        .hero-copy,
        .metric strong,
        .metric span,
        .section-heading p,
        .product-meta,
        .product-link,
        .price,
        .deal-card p,
        .editorial-card a,
        .editorial-card p,
        .tag,
        .newsletter p,
        .footer-inner p {
          color: CanvasText;
        }

        .text-link {
          color: LinkText;
        }
      }
    </style>
  </head>
  <body>
    <a class="skip-link" href="#maincontent">Skip to main content</a>
    <div id="root"></div>

    <script>
      const products = [
        {
          name: "Orbit Weekender Tote",
          category: "Travel",
          price: "$148",
          description: "Water-resistant recycled canvas with a structured laptop sleeve.",
          swatch: "#22d3ee",
