          copy: "Pair durable carryalls with modular packing cubes before your next escape.",
          color: "#d946ef"
        },
        {
          label: "Members",
          title: "Free express shipping over $75",
          copy: "Northstar Circle members get faster doorstep delivery all week.",
          color: "#facc15"
        }
      ];

      const articles = [
        {
          tag: "Style guide",
          title: "A capsule wardrobe that actually keeps pace",
          copy: "Our editors build a nine-piece system for office days, weekends, and late flights.",
          color: "#4338ca"
        },
        {
          tag: "At home",
