        }
      ];

      const navItems = ["Featured", "Deals", "Editorial"];

      function slugify(value) {
        return value.toLowerCase().replaceAll(" ", "-");
      }

      function Header() {
        return `
          <header class="site-header">
            <div class="nav-shell">
              <a class="brand" href="#maincontent" aria-label="Northstar Goods home">
                <span class="brand-mark" aria-hidden="true">N</span>
                <span>Northstar Goods</span>
              </a>
              <nav class="primary-nav" aria-label="Primary">
                <ul>
                  ${navItems
                    .map((item) => `<li><a href="#${item.toLowerCase()}">${item}</a></li>`)
                    .join("")}
                </ul>
              </nav>
              <div class="header-actions">
                <a class="pill-button" href="#featured">Shop new arrivals</a>
                <button class="icon-button" type="button" aria-label="Bag: view shopping cart, 2 items">
                  <span aria-hidden="true">Bag</span>
                  <span class="cart-count" aria-hidden="true">2</span>
                </button>
              </div>
            </div>
          </header>
        `;
      }

      function Hero() {
        return `
          <section class="section hero" aria-labelledby="hero-heading">
            <div>
              <p class="eyebrow">New season drop</p>
              <h1 id="hero-heading">Retail energy for everyday life.</h1>
              <p class="hero-copy">
                Discover refined apparel, home goods, travel gear, and design-led tech curated
                for customers who move between city days and quiet nights.
              </p>
              <div class="hero-actions">
                <a class="pill-button" href="#featured">Explore featured products</a>
                <a class="text-link" href="#editorial">Read the edit <span aria-hidden="true">→</span></a>
