            ${linkText ? `<a class="text-link" href="#${id}">${linkText} <span aria-hidden="true">→</span></a>` : ""}
          </div>
        `;
      }

      function ProductCard(product) {
        return `
          <li>
            <article class="product-card" id="${slugify(product.name)}" style="--swatch: ${product.swatch}; --shape: ${product.shape};">
