      function FeaturedProducts() {
        return `
          <section class="section" id="featured" aria-labelledby="featured-heading">
            ${SectionHeading({
              id: "featured",
              title: "Featured products",
              copy: "Signature pieces selected for standout craft, long-wear utility, and premium finishes.",
              linkText: "View all products"
            })}
            <ul class="product-grid">
              ${products.map(ProductCard).join("")}
            </ul>
          </section>
        `;
      }

      function DealCard(deal) {
        return `
          <li>
            <article class="deal-card" style="--deal-color: ${deal.color};">
              <span class="deal-label">${deal.label}</span>
              <h3>${deal.title}</h3>
              <p>${deal.copy}</p>
            </article>
          </li>
        `;
      }

      function Deals() {
        return `
          <section class="deals" id="deals" aria-labelledby="deals-heading">
            <div class="section">
              ${SectionHeading({
                id: "deals",
                title: "Deals worth the detour",
                copy: "Time-boxed savings and member perks with clear terms, sharp pricing, and no treasure hunt.",
                linkText: "Browse current deals"
